class InputCell:
    def __init__(self, initial_value):
        self.value = initial_value
        # dependents are compute cells that directly depend on this cell
        self._dependents = set()

    def set_value(self, new_value):
        # If value doesn't change, do nothing.
        if self.value == new_value:
            return
        self.value = new_value

        # Collect all affected compute cells reachable from this input
        affected = set()
        stack = list(self._dependents)
        while stack:
            cell = stack.pop()
            if cell in affected:
                continue
            affected.add(cell)
            stack.extend(cell._dependents)

        if not affected:
            return

        # Save previous values to decide which callbacks to call
        previous_values = {cell: cell.value for cell in affected}

        # Recompute values in a topological order using recursion
        processed = set()

        def recompute(cell):
            if cell in processed:
                return
            # Ensure inputs that are compute cells are updated first
            for inp in cell.inputs:
                if isinstance(inp, ComputeCell) and inp in affected:
                    recompute(inp)
            # Compute new value
            new_val = cell.compute_function([inp.value for inp in cell.inputs])
            cell.value = new_val
            processed.add(cell)

        # Recompute all affected cells
        for cell in list(affected):
            recompute(cell)

        # After reaching a stable state, call callbacks for cells whose value changed
        for cell in affected:
            old = previous_values.get(cell)
            new = cell.value
            if old != new:
                # Call callbacks in registration order
                for cb in list(cell._callbacks):
                    try:
                        cb(new)
                    except Exception:
                        # Swallow exceptions from callbacks to not break propagation
                        pass


class ComputeCell:
    def __init__(self, inputs, compute_function):
        self.inputs = list(inputs)
        self.compute_function = compute_function
        self._callbacks = []
        self._dependents = set()
        # Register self as dependent on inputs
        for inp in self.inputs:
            if not hasattr(inp, "_dependents"):
                inp._dependents = set()
            inp._dependents.add(self)
        # Compute initial value
        self.value = compute_function([inp.value for inp in self.inputs])

    def add_callback(self, callback):
        if callback not in self._callbacks:
            self._callbacks.append(callback)

    def remove_callback(self, callback):
        if callback in self._callbacks:
            self._callbacks.remove(callback)
